import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String mode = sc.next();
        GameSettings game = new GameSettings();
        if (mode.equals("UPDATE")) {
            String diff = sc.next();
            int vol = sc.nextInt();
            game.setDifficulty(diff);
            game.setVolume(vol);
        }
        game.print();
    }
}

class GameSettings {
    String difficulty;
    boolean sound;
    int volume;

    GameSettings() {
        difficulty = "Normal";
        sound = true;
        volume = 50;
    }

    void setDifficulty(String d) {
        difficulty = d;
    }

    void setVolume(int v) {
        volume = v;
    }

    void print() {
        System.out.println("Difficulty: " + difficulty);
        System.out.println("Sound: " + (sound ? "on" : "off"));
        System.out.println("Volume: " + volume);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String category = sc.next();
        int qty = sc.nextInt();
        Ticket t = new Ticket(category, qty);
        t.print();
    }
}

class Ticket {
    String category;
    int quantity;
    int unitPrice;
    int total;

    Ticket(String category, int quantity) {
        this.category = category;
        this.quantity = quantity;
        if (category.equals("VIP")) {
            unitPrice = 250;
        } else {
            unitPrice = 100;
        }
        total = unitPrice * quantity;
    }

    void print() {
        System.out.println("Category: " + category);
        System.out.println("Tickets: " + quantity);
        System.out.println("Total: " + total);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine().trim();
        String[] parts = line.split(" ");
        Box box;
        if (parts.length == 1) {
            int side = Integer.parseInt(parts[0]);
            box = new Box(side);
        } else {
            int l = Integer.parseInt(parts[0]);
            int w = Integer.parseInt(parts[1]);
            box = new Box(l, w);
        }
        System.out.println("Volume: " + box.volume());
    }
}

class Box {
    int length;
    int width;
    int height;

    Box(int side) {
        length = side;
        width = side;
        height = side;
    }

    Box(int length, int width) {
        this.length = length;
        this.width = width;
        height = 1;
    }

    int volume() {
        return length * width * height;
    }
}

